    r0, r1 = min(r for r, _ in zero_cells), max(r for r, _ in zero_cells)
    c0, c1 = min(c for _, c in zero_cells), max(c for _, c in zero_cells)
    output = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]

    outside = [row[:] for row in grid]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            outside[r][c] = background

    shape_counts = Counter()
    seen = set()
    for r in range(rows):
        for c in range(cols):
            color = outside[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < rows and 0 <= ny < cols and (nx, ny) not in seen
                            and outside[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            min_r = min(x for x, _ in cells)
            min_c = min(y for _, y in cells)
            shape = (color, tuple(sorted((x - min_r, y - min_c) for x, y in cells)))
            shape_counts[shape] += 1

    seeds = {}
    for r in range(len(output)):
        for c in range(len(output[0])):
            color = output[r][c]
            if color not in (0, background):
                seeds.setdefault(color, []).append((r, c))

