        for c in range(cols):
            color = outside[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                x, y = stack.pop()
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = x + dx, y + dy
                        if ((dx or dy) and 0 <= nx < rows and 0 <= ny < cols
                                and (nx, ny) not in seen and outside[nx][ny] == color):
                            seen.add((nx, ny))
